import{_ as n,h as o,i as a,c as r,v as i,p as s,x as l,m as p,e as m,S as d}from"./chunks/framework.Dvtg8yj2.js";const E=JSON.parse('{"title":"Tiling 与融合","description":"","frontmatter":{"title":"Tiling 与融合","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kernel-fusion-tiling.md","filePath":"llm/kernel-fusion-tiling.md","lastUpdated":1788454257000}'),M={name:"llm/kernel-fusion-tiling.md"};function h(c,e,A,u,B,f){const t=o("Mermaid");return a(),r("div",null,[e[1]||(e[1]=i('<h1 id="tiling-与融合" tabindex="-1">Tiling 与融合 <a class="header-anchor" href="#tiling-与融合" aria-label="Permalink to &quot;Tiling 与融合&quot;">​</a></h1><div class="epigraph"><p>把大矩阵切成能住进片上存储的块，并在块内把后续逐元素运算一起做完：少的是 HBM 往返，不是渐近 FLOP。</p><footer>—— NVIDIA CUTLASS / CUDA 编程模型中的 tiling 与 kernel fusion 实践，对照架构白皮书的存储层次</footer></div><p>LLM 的计算图在框架里是一串算子：线性、偏置、激活、残差、归一化、注意力。若每个算子都是独立 kernel，中间激活写回 HBM 再读出，算术强度被一次次往返打穿，<a href="/llm/hbm-roofline">屋顶线</a> 停在斜边上。Tiling 解决「一块数据如何在片上复用」；融合解决「相邻算子如何共用这一块、不要拆核」。二者经常一起出现：没有合适的 tile，融合核装不下；没有融合，tile 算完仍要为下一个算子重新从 HBM 取。</p><p>本篇把切块与融合写成同一套 IO 账，并区分编译器融合与手写融合。不把某一框架的加速比写成定律。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一次 \\(M\\times K\\) 与 \\(K\\times N\\) 的 GEMM，朴素三重循环对 \\(A\\)、\\(B\\) 几乎没有复用，每次 FMA 都打全局内存。经典解法是分块：选 \\(B_m,B_n,B_k\\)，使 \\(A\\) 的 \\(B_m\\times B_k\\) 与 \\(B\\) 的 \\(B_k\\times B_n\\) 能进共享内存甚至寄存器，内层把 \\(K\\) 维扫完再换下一块。算术强度大约按 tile 边长上升，直到受 smem / 寄存器容量限制。注意力的 \\(QK^\\top\\) 与 \\(PV\\) 是同一逻辑：不切块就要物化 \\(n\\times n\\)，切块则必须处理 softmax 的全局归一化，见 <a href="/llm/flashattention">FlashAttention</a>。</p><p>融合是另一轴。GEMM 之后的偏置、Gelu、残差加，元素级运算的 FLOP 很少，但流量与 GEMM 输出同阶。拆成两核，等于把刚写出的矩阵再读一遍。把 epilogue 接在 tile 写回之前，输出只走一次 HBM。问题变成：哪些算子的数据依赖允许「算完一块立刻做下一算子」，哪些必须看到完整归约（softmax、RMSNorm 的均方根）因而只能块内递推或放弃融合。</p><h3 id="融合并不自动提高占用" tabindex="-1">融合并不自动提高占用 <a class="header-anchor" href="#融合并不自动提高占用" aria-label="Permalink to &quot;融合并不自动提高占用&quot;">​</a></h3><p>把三个小核合成一个大核，启动次数下降，但每个核的寄存器与 smem 上升，驻留 CTA 数可能下降。若融合后的核在 decode 的 \\(M=1\\) 形状上更胖、更少并行，墙钟可能不变甚至变差。Tiling 也有同样的张力：tile 太大，占用率低、尾块浪费；tile 太小，复用不够、bank 与 MMA 形状还可能对不齐。切块大小是搜索问题，不是「越大越好」。</p><p><span class="marginnote">框架里看到 <code>fused_add_rms_norm</code> 或 <code>cublasLt</code> 的 epilogue，只说明图上少了一个核，不说明 tile 已经按本机架构选对。缺了 tiling 的融合，仍可能是「一个大而慢的逐元素核」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程上按依赖方向选融合粒度。</p><p><strong>垂直融合（producer–consumer）</strong>：同一数据路径上下游，如 Linear → Bias → Silu，或注意力里的 GEMM → softmax → GEMM。中间结果留在寄存器或 smem，只把最终向量写 HBM。CUTLASS 的 epilogue、cuBLASLt 的 bias+activation、FlashAttention 的块内在线 softmax，都属于这一类。</p><p><strong>水平融合</strong>：彼此独立、形状相同的算子绑到一次启动，例如一组小 GEMM、多头里按头并行。它减启动税，不减单条路径的 HBM 流量，和 <a href="/llm/cuda-graph">CUDA Graph</a> 部分重叠——Graph 录的是已有核，水平融合是把核真的写在一起。</p><p>Tiling 的选择顺序通常是：先定 MMA 原子形状（16×8×16 一类，随代而变），再定 CTA tile 为原子的整数倍，再定 K 维流水的 stage 数使 smem 装得下双缓冲或多缓冲。Decode 的 \\(M\\) 很小，CTA tile 在 \\(M\\) 上无法做大，只能沿 \\(N\\)、批与头去堆并行，否则融合得再好也填不满阵列。</p>',15)),(a(),s(d,null,{default:l(()=>[m(t,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20naive%20%5B%22%E6%8B%86%E6%A0%B8%22%5D%0A%20%20%20%20G1%5B%22GEMM%20%E5%86%99%20HBM%22%5D%20--%3E%20E1%5B%22%E6%BF%80%E6%B4%BB%E8%AF%BB%20HBM%22%5D%0A%20%20end%0A%20%20subgraph%20fused%20%5B%22%E5%88%87%E5%9D%97%E8%9E%8D%E5%90%88%22%5D%0A%20%20%20%20T%5B%22%E8%A3%85%E5%85%A5%20tile%22%5D%20--%3E%20MMA%5B%22MMA%22%5D%0A%20%20%20%20MMA%20--%3E%20EP%5B%22%E7%89%87%E4%B8%8A%20epilogue%22%5D%0A%20%20%20%20EP%20--%3E%20OUT%5B%22%E5%86%99%E5%9B%9E%E4%B8%80%E6%AC%A1%22%5D%0A%20%20end%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<h3 id="编译器融合与手写核" tabindex="-1">编译器融合与手写核 <a class="header-anchor" href="#编译器融合与手写核" aria-label="Permalink to &quot;编译器融合与手写核&quot;">​</a></h3><p>nvFuser、Torch Inductor、XLA 一类会把逐元素链收成点核，有时也能把小型归约融进去。它们擅长「能分析别名与形状」的静态图，短于需要在线 softmax、分页 KV、warp 特化的注意力。生产里常见分工：MLP 的 GEMM+epilogue 交给 <a href="/llm/cublas-cudnn">cuBLAS / cuDNN</a> 或 <a href="/llm/cutlass">CUTLASS</a> 模板；注意力交给手写或厂商 FMHA；剩余点算子交给编译器。强行让编译器生成 Hopper 上的 TMA+WGMMA 注意力，目前不是默认路径。</p><p>形状动态时，融合核要为若干桶各编译一份，或在核内用谓词处理尾块。桶太多，二进制与指令缓存膨胀；桶太少，padding 浪费算力。这和 Graph 分桶是同一调度问题，只是发生在编译期而不是捕获期。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Tiling 提升强度，是因为 \\(A\\) 的一块被 \\(B_n\\) 列复用、\\(B\\) 的一块被 \\(B_m\\) 行复用。融合提升强度，是因为下游逐元素不引入新的大规模矩阵流量，只在已有输出寄存器上多几次 FMA 或特殊函数。两者相乘：一个设计良好的 MLP 核，HBM 只看见权重、输入激活和最终输出；中间的宽展开激活从不落盘。若融合点选在必须全局归约之处却不做在线算法，核只能把部分和写回，融合名存实亡。</p><p>异步拷贝改变的是 tiling 的时间轴，不是切块几何。Ampere 用 <code>cp.async</code> 把下一块 \\(K\\) 搬进 smem 的同时算当前块；Hopper 用 <a href="/llm/hopper-tma">TMA</a> 与 <a href="/llm/sw-pipeline-buffer">软件流水</a> 把 stage 加深。没有切块，异步没有「下一块」可搬；没有融合，搬来的块算完仍要为 softmax 或激活再走一遍 HBM。FA3 把切块、融合、异步叠在同一注意力核里，见 <a href="/llm/flashattention-3">FlashAttention-3</a>。</p><p><span class="marginnote">「融合」在产品文案里有时只指 epilogue（bias、ReLU），有时指跨层的 RMSNorm+GEMM。讨论性能时要写清融了哪些边。只融 bias 的 GEMM，对 decode 带宽墙的帮助远小于把注意力两段 GEMM 留在 SRAM。</span></p><h3 id="数值与融合顺序" tabindex="-1">数值与融合顺序 <a class="header-anchor" href="#数值与融合顺序" aria-label="Permalink to &quot;数值与融合顺序&quot;">​</a></h3><p>把 LayerNorm 融进前一层的 epilogue，均值和方差必须在当前 tile 能算出来，或改成 RMSNorm 那种按向量的局部量。半精度下，先写 HBM 再在高精核里归约，与在寄存器里用 FP32 累加再写回，误差不同。融合要以对照测试钉死：同一输入、同一 dtype 下与拆核实现比最大绝对误差。不能默认「更快的核数值等价」。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要为融合而融合：两个都是大 GEMM、中间激活要留给反向的训练图，可能更该存下来而不是重算，除非像注意力那样 \\(n^2\\) 中间量不可接受。不要把动态控制流（MoE 路由、变长 droput 掩码）塞进静态 tile 核后还假设编译器能解开。不要跨架构复制 tile 尺寸：A100 上好的 \\(128\\times 256\\times 32\\) 在 H100 上可能不是 WGMMA 的舒适区。</p><p>训练与推理的融合合同不同。训练要为反向保留或重算中间；推理可以丢掉。同一套 CUTLASS 模板，epilogue 在两边不是同一份。服务侧还要把融合核的占用与连续批处理的变长形状一起考虑：融合提高了单形状峰值，却可能让形状分桶更碎。</p><p><span class="marginnote">出处：CUDA 编程指南的存储层次与 Occupancy；CUTLASS 文档的 GEMM tiling / epilogue；架构白皮书中 SM 的共享内存与 Tensor Core 容量。FlashAttention 论文是「切块 + 融合 + 在线归约」的注意力特例，不是通用融合理论的替代。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Tiling 把工作切进 smem / 寄存器以增加复用；融合让相邻算子共用这些块，避免中间激活落 HBM。</li><li>垂直融合减流量，水平融合减启动；二者都可能因占用率下降而在小形状上失效。</li><li>Tile 尺寸应先对齐 MMA 原子，再填满流水 stage，最后才用搜索微调。</li><li>编译器适合逐元素链；注意力与 warp 特化仍手写或走厂商库。</li><li>融合改变数值归约顺序，必须做误差对照。</li><li>出处：CUDA / CUTLASS 文档与 GPU 架构白皮书；注意力切块见 FlashAttention。</li></ul>',15))])}const _=n(M,[["render",h]]);export{E as __pageData,_ as default};
